// TH14 synthetic bullet aliases (see transcribe/th14/touhou-bullets.ecl).
// Native type 0..23 -> modern same number; native 24..42 -> modern +1.
const TH14_BALL2: int = 432;   // native type 5

// TH14 v1.00b Extra Boss5 non-spell (st07bs.ecl.txt:468-521).
// Source rank is the !O (Extra) branch only. Entry is the whole Boss5 sub:
// timerReset at t=0, 60+80 prelude, then Boss5_at / Boss5_at2 run async while
// the boss keeps hopping with moveRand until the slot-0 interrupt at 3000.

const TIME_LIMIT: int = 3424;   // 120 opening + 3000 source phase + 304 tail
const OPENING_BUFFER: int = 120;
const SOURCE_ENTRY_FRAMES: int = 3000;   // setInterrupt(0, 3300, 50*60, "BossCard5")

// 412 moveRand(60, 4, 1.0) sample recipe (transcribe/th16/movement.md), reused
// with this phase's moveLimit(0,128,280,64): x in [-140,140], y in [96,160].
// Shared slots: int0 = next-step count, fx0/fx1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, 0.05rad expressed as nearest BAM ints.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Boss5_at: emitter 0, fixed-direction 6-ring at a random point near the boss,
// six offset rings per 8 frames, base angle advancing 10 degrees per step.
async sub boss5_at() {
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 4);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 6, 1);
    sh_angle(0, 0deg, 30deg);        // etAngle second arg 0.5235988 rad, unused at 1 layer
    sh_speed(0, 4fx, 0fx);           // etSpeed(4.0, 1.0) at one layer
    sh_dist(0, -16fx);               // etEx ANIM a=1: position -= 4*velocity at birth
    var c: angle = (rand(65536) - 32768) as angle;   // %C = RANDRAD
    for n in 0..18000 {
        var ca: angle = (rand(65536) - 32768) as angle;          // circlePos angle
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx; // RANDF
        var cr: fx = u * 16fx;
        var cx: fx = cr * cos(ca);
        var cy: fx = cr * sin(ca);
        sh_offset_abs(0, $self_x + cx + 64fx, $self_y + cy);
        sh_angle(0, c, 30deg);
        for f in 0..6 {
            var oa: angle = (rand(65536) - 32768) as angle;
            var ou: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
            sh_offset_rad(0, oa, ou * 8fx);
            sh_fire(0);
        }
        c = c + 10deg;
        wait(8);
    }
}

// Boss5_at2: emitter 1. Source x is _f(_S(%A + %FINAL_X) - 64): the float sum
// is cast to int, 64 subtracted, then cast back (see report.md for the raw-op note).
async sub boss5_at2() {
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 4);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 6, 1);
    sh_angle(0, 0deg, 30deg);
    sh_speed(0, 4fx, 0fx);
    sh_dist(0, -16fx);
    var c: angle = (rand(65536) - 32768) as angle;
    wait(4);
    for n in 0..18000 {
        var ca: angle = (rand(65536) - 32768) as angle;
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
        var cr: fx = u * 16fx;
        var cx: fx = cr * cos(ca);
        var cy: fx = cr * sin(ca);
        sh_offset_abs(0, (($self_x + cx) as int - 64) as fx, $self_y + cy);
        sh_angle(0, c, 30deg);
        for f in 0..6 {
            var oa: angle = (rand(65536) - 32768) as angle;
            var ou: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
            sh_offset_rad(0, oa, ou * 8fx);
            sh_fire(0);
        }
        c = c + 10deg;
        wait(8);
    }
}

async sub boss5_main() {
    set_invuln(65535);                       // invulnerable training shell
    set_hitbox(24fx);                        // Boss(): setHitbox(48,48) circle, r=24
    set_hurtbox(24fx);
    // moveVel(0,0) / moveVelTime(0,0,0,0) / movePosTime(0,0,...): clear residual
    // velocity and cancel the previous position interpolation on entry.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);  // movePosTime(60, 4, 0, 128)
    wait(60);
    // moveLimit(0,128,280,64) lives in the movement helper above.
    wait(80);                                // 60+80 prelude inside the source timer
    spawn boss5_at();                        // line 512, both async at source t=140
    spawn boss5_at2();                       // line 513
    var t: int = 140;
    loop {
        var step: int = 120;
        if t + 120 > SOURCE_ENTRY_FRAMES { step = SOURCE_ENTRY_FRAMES - t; }
        card_wait(step);
        t = t + step;
        if t >= SOURCE_ENTRY_FRAMES { break; }
        card_move_rand();                    // Boss5_1388: wait(120); moveRand(...)
    }
    // Source slot-0 interrupt at 3000: stop emitting and retire the enemy.
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14300, 0, 0, 0, boss5_main);   // lifeSet(14300)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
